const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '入射光线' },
      { kind: 'text', payload: '法线' },
      { kind: 'text', payload: '反射光线' },
      { kind: 'text', payload: '反射角' }
    ];
  },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 560;
    var H = (input && input.viewport && input.viewport.heightDu) || 400;
    var cx = W * 0.5;
    var mirrorY = H * 0.78;
    var arm = Math.min(W * 0.28, H * 0.42);
    var O = { x: cx, y: mirrorY };
    var A = { x: cx - arm, y: mirrorY - arm };
    var B = { x: cx + arm, y: mirrorY - arm };
    var N = { x: cx, y: mirrorY - H * 0.62 };
    var x0 = W * 0.10;
    var x1 = W * 0.90;
    var mirror = visualSdk.polyline([[x0, mirrorY], [x1, mirrorY]]);
    var hatch = [];
    var step = W * 0.07;
    var hx = x0 + step * 0.5;
    while (hx < x1) {
      hatch = hatch.concat(visualSdk.polyline([[hx, mirrorY], [hx - step * 0.45, mirrorY + step * 0.5]]));
      hx += step;
    }
    var normal = visualSdk.polyline([[N.x, N.y], [O.x, O.y]]);
    var incident = visualSdk.arrow(A.x, A.y, O.x, O.y, {});
    var reflected = visualSdk.arrow(O.x, O.y, B.x, B.y, {});
    var arcR = arm * 0.5;
    var angleArc = visualSdk.arc(O.x, O.y, arcR, -90, -45);
    var lInc = { x: cx - arm * 0.75, y: mirrorY - arm * 0.65 };
    var lRef = { x: cx + arm * 0.75, y: mirrorY - arm * 0.65 };
    var lNorm = { x: N.x + 14, y: N.y + 12 };
    var bis = (-67.5) * Math.PI / 180;
    var lAng = { x: O.x + Math.cos(bis) * arcR * 1.35, y: O.y + Math.sin(bis) * arcR * 1.35 };
    var labelStyle = { fontSize: 16, fill: '#111827', textAnchor: 'middle', dominantBaseline: 'middle' };
    return {
      schemaVersion: 1,
      sceneId: 'reflection-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'hatch', commands: hatch },
        { id: 'mirror', commands: mirror },
        { id: 'normal', commands: normal },
        { id: 'incident', commands: incident },
        { id: 'reflected', commands: reflected },
        { id: 'angleArc', commands: angleArc }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'hatch', stroke: '#94a3b8', strokeWidth: 1.2, fill: 'none' },
        { type: 'path', pathId: 'mirror', stroke: '#334155', strokeWidth: 2, fill: 'none' },
        { type: 'path', pathId: 'normal', stroke: '#475569', strokeWidth: 1.5, fill: 'none', strokeDasharray: [7, 5] },
        { type: 'path', pathId: 'incident', stroke: '#1d4ed8', strokeWidth: 2, fill: 'none' },
        { type: 'path', pathId: 'reflected', stroke: '#1d4ed8', strokeWidth: 2, fill: 'none' },
        { type: 'path', pathId: 'angleArc', stroke: '#b45309', strokeWidth: 1.8, fill: 'none' },
        { type: 'label', x: lInc.x, y: lInc.y, text: '入射光线', fontSize: labelStyle.fontSize, fill: labelStyle.fill, textAnchor: labelStyle.textAnchor, dominantBaseline: labelStyle.dominantBaseline },
        { type: 'label', x: lNorm.x, y: lNorm.y, text: '法线', fontSize: labelStyle.fontSize, fill: labelStyle.fill, textAnchor: 'start', dominantBaseline: 'middle' },
        { type: 'label', x: lRef.x, y: lRef.y, text: '反射光线', fontSize: labelStyle.fontSize, fill: labelStyle.fill, textAnchor: labelStyle.textAnchor, dominantBaseline: labelStyle.dominantBaseline },
        { type: 'label', x: lAng.x, y: lAng.y, text: '反射角', fontSize: labelStyle.fontSize, fill: labelStyle.fill, textAnchor: labelStyle.textAnchor, dominantBaseline: labelStyle.dominantBaseline }
      ] }
    };
  }
};
